head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // fn_HideDebugCtrls();
        // fn_SetCode();
        //    fn_read_schdl();
        scwin.hideDebugCtrls();
        await scwin.setCode();
        $c.libRoundPanel.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30609.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30609.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30609.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save); ///('trs_Save.OnFail()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30609.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("이수 처리하였습니다.");
        const fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30609.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_COMPLT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30609.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name dts_Company_OnFilter
 * @description Company On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_Company_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30609.dts_Company_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_DISCLS_EDU_CRS_NM_onselchange
 * @description cmb_DISCLS_EDU_CRS_NM onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_DISCLS_EDU_CRS_NM_onselchange = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30609.cmb_DISCLS_EDU_CRS_NM_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description 상용안함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Edunm",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Edunm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Edunm.insertRow();
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const parentWin = $c.frame.path("../");
    const paramObj = parentWin.gParamObj;
    if (paramObj === undefined) return;
    txb_ISUR_CD.setValue(paramObj.param1);
    txb_EDU_KIND_CD.setValue(paramObj.param2);
    txb_EDU_KIND_NM.setValue(paramObj.param3);
    txb_EDU_PARTC_ID.setValue(paramObj.param4);
    const vEDU_KIND_CD = txb_EDU_KIND_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Company",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Company=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    await scwin.search();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vEDU_ID = cmb_DISCLS_EDU_CRS_NM.getValue();
    const vISUR_CD = txb_ISUR_CD.getValue();
    const vIEDU_KIND_CD = txb_EDU_KIND_CD.getValue();
    const vIEDU_PARTC_ID = txb_EDU_PARTC_ID.getValue();
    url += "&EDU_ID=" + vEDU_ID;
    url += "&SCREN_ID=" + "ULDSTF30609.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Edunm",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Edunm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    txb_ISUR_CD.setValue(vISUR_CD);
    txb_EDU_KIND_CD.setValue(vIEDU_KIND_CD);
    txb_EDU_PARTC_ID.setValue(vIEDU_PARTC_ID);
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (confirm("이수처리하시겠습니까?")) {
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ListedCompany.do",
            ref : "dts_Edunm",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else {
        return false;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    txb_EDU_KIND_CD.hide();
    txb_ISUR_CD.hide();
    txb_EDU_ID.hide();
    txb_EDU_PARTC_ID.hide();
};
